window.UNF_GLOSSARY=[{"term":"A Map of the Web3 Industry","name":"","def":"A structural map of the Web3 industry organized by technical stack and business function, spanning base-layer infrastructure, middleware and tooling, user-facing applications, and supporting service ecosystems.","path":"learn/220-en.html","title":"A Map of the Web3 Industry","g":"web3","isDef":1},{"term":"Accumulation/Distribution","name":"","def":"Track whether volume has been consistently accompanying closes near the top or bottom of each bar's high-low range, accumulating those weighted volumes over time.","path":"learn/77-en.html","title":"Accumulation/Distribution","g":"market","isDef":1},{"term":"ADP National Employment Report","name":"","def":"An ADP estimate of changes in private employment using payroll data.","path":"info/learn/20-en.html","title":"ADP National Employment Report","g":"info","isDef":1},{"term":"ADR","name":"","def":"Average Daily Range (ADR) calculates (High − Low) for each of the past N days and averages those daily high-low spans, describing 'how far price typically travels between the day's high and low within a single session.' Because it usually excludes overnight gaps from yesterday's close to today's open, it differs from ATR.","path":"learn/29-en.html","title":"ADR","g":"market","isDef":1},{"term":"Advance Retail Sales","name":"","def":"Dollar sales at retailers and food services, mainly informing goods spending rather than the full range of household services.","path":"info/learn/31-en.html","title":"Advance Retail Sales","g":"info","isDef":1},{"term":"Advance/Decline","name":"","def":"The Advance/Decline Line (A/D Line) measures whether a broad universe of stocks is participating in a market move—it is not derived from a single stock's candlesticks.","path":"learn/104-en.html","title":"Advance/Decline","g":"market","isDef":1},{"term":"ADX","name":"","def":"First answer whether the market has been moving persistently in one direction before deciding whether a trend is worth studying further.","path":"learn/41-en.html","title":"ADX","g":"market","isDef":1},{"term":"Aggregators & Launchpads","name":"","def":"DEX aggregators are routing protocols that split orders across multiple liquidity venues to minimize slippage and execution costs, while Launchpads (IDOs) facilitate early public token sales and fundraising on-chain.","path":"learn/226-en.html","title":"Aggregators & Launchpads","g":"web3","isDef":1},{"term":"AI × Web3","name":"","def":"The intersection of Artificial Intelligence (AI) inference and automation with blockchain-based decentralized incentives, cryptographic verification, and on-chain settlement.","path":"learn/218-en.html","title":"AI × Web3","g":"web3","isDef":1},{"term":"Airdrops & Sybil Attacks","name":"","def":"An airdrop is a free distribution of tokens to qualifying addresses, typically based on past use of a product (a retroactive airdrop) or on completed tasks and accumulated points.","path":"learn/200-en.html","title":"Airdrops & Sybil Attacks","g":"web3","isDef":1},{"term":"ALMA","name":"","def":"Use a Gaussian bell-curve weighted price average to read trend direction while reducing single-bar jumpiness.","path":"learn/50-en.html","title":"ALMA","g":"market","isDef":1},{"term":"Anchored VWAP","name":"","def":"Anchored VWAP (AVWAP) calculates the volume-weighted average price starting from a specific bar or event date that you choose.","path":"learn/93-en.html","title":"Anchored VWAP","g":"market","isDef":1},{"term":"Aroon","name":"","def":"Measure how recently the highest high and lowest low inside a lookback window occurred.","path":"learn/43-en.html","title":"Aroon","g":"market","isDef":1},{"term":"Aroon Oscillator","name":"","def":"Compress the lead between the two Aroon lines into a single curve: Aroon Oscillator = Aroon Up − Aroon Down.","path":"learn/44-en.html","title":"Aroon Oscillator","g":"market","isDef":1},{"term":"ATR","name":"","def":"Average True Range (ATR) measures how much a single candlestick typically spans over a recent window, including both the bar's high-low range and any gap from the prior bar's close.","path":"learn/27-en.html","title":"ATR","g":"market","isDef":1},{"term":"ATR Trailing Stop","name":"","def":"ATR Trailing Stop uses recent typical bar volatility to leave breathing room for an open position and ratchets the exit reference in the favorable direction as price advances.","path":"learn/91-en.html","title":"ATR Trailing Stop","g":"market","isDef":1},{"term":"ATRP/NATR","name":"","def":"Average True Range Percent / Normalized ATR (ATRP / NATR) typically divides ATR by the closing price and multiplies by 100, answering 'what percentage of current price does a typical single-bar move represent?' Converting raw price units into percentages places high-priced and low-priced assets on a comparable relative volatility scale.","path":"learn/28-en.html","title":"ATRP/NATR","g":"market","isDef":1},{"term":"Auction Market Theory","name":"","def":"Auction Market Theory (AMT) views market movement as a continuous two-way auction searching for price zones where buyers and sellers willingly trade in size, helping you answer whether current prices are being accepted (balanced rotation) or rejected (imbalanced search for a new value area).","path":"learn/126-en.html","title":"Auction Market Theory","g":"market","isDef":1},{"term":"Average Hourly Earnings","name":"","def":"Average gross hourly earnings of private nonfarm employees.","path":"info/learn/14-en.html","title":"Average Hourly Earnings","g":"info","isDef":1},{"term":"Average Weekly Hours","name":"","def":"Average weekly hours for private nonfarm employees.","path":"info/learn/15-en.html","title":"Average Weekly Hours","g":"info","isDef":1},{"term":"Averaging Down vs Adding to Winners","name":"","def":"Averaging down means buying more at a lower price while a position is losing, which lowers the average cost.","path":"learn/171-en.html","title":"Averaging Down vs Adding to Winners","g":"market","isDef":1},{"term":"Awesome Oscillator/AO","name":"","def":"Compare a short-term simple moving average of bar midpoints against a longer-term simple moving average of bar midpoints to see whether near-term midpoint momentum leads or lags the broader backdrop.","path":"learn/63-en.html","title":"Awesome Oscillator/AO","g":"market","isDef":1},{"term":"Backtesting & Overfitting","name":"","def":"Backtesting is the quantitative simulation of a codified trading rule across historical market data; Net Backtest Return = Gross Simulated Profit - Cumulative Commissions - Cumulative Slippage.","path":"learn/190-en.html","title":"Backtesting & Overfitting","g":"market","isDef":1},{"term":"Bank of England MPC Rate Decision","name":"","def":"The Bank of England MPC Rate Decision, announced eight times a year by the Monetary Policy Committee (MPC) on scheduled Thursdays at 12:00 noon London time alongside the Monetary Policy Summary and Minutes (plus the quarterly Monetary Policy Report and press conference in February, May, August, and November), sets the official Bank Rate for the United Kingdom.","path":"info/learn/68-en.html","title":"Bank of England MPC Rate Decision","g":"info","isDef":1},{"term":"Bank of Japan Monetary Policy Decision","name":"","def":"The Bank of Japan (BOJ) Monetary Policy Decision, announced eight times a year by the BOJ Policy Board at the conclusion of its two-day meeting (typically between 11:30 a.m. and 1:00 p.m.","path":"info/learn/69-en.html","title":"Bank of Japan Monetary Policy Decision","g":"info","isDef":1},{"term":"Basis & Premium","name":"","def":"This lesson uses the common crypto convention: basis = futures price − spot price (some texts use spot − futures; check the platform), and premium rate = basis ÷ spot price.","path":"learn/163-en.html","title":"Basis & Premium","g":"market","isDef":1},{"term":"Beginner Safety: Scams & Money Management","name":"","def":"Common scams include investment schemes or “copy-trade” offers promising steady high returns, impostors posing as support or friends to obtain codes and recovery phrases, fake websites and apps (phishing), “pig-butchering” schemes where a stranger builds trust over time before steering you into an investment, and pump-and-dump chat groups.","path":"learn/183-en.html","title":"Beginner Safety: Scams & Money Management","g":"web3","isDef":1},{"term":"Bitcoin vs Ethereum","name":"","def":"Bitcoin (BTC) is the first public chain, capped at 21 million coins, with new issuance halving about every 210,000 blocks (roughly four years); it is designed for simple, stable value transfer and storage.","path":"learn/197-en.html","title":"Bitcoin vs Ethereum","g":"web3","isDef":1},{"term":"Blockchain & the Trilemma","name":"","def":"A blockchain is a ledger kept by many nodes and chained in time order: transactions from a period are packed into a “block”, and each block carries the hash (data fingerprint) of the previous one, so altering any page breaks every fingerprint after it.","path":"learn/196-en.html","title":"Blockchain & the Trilemma","g":"web3","isDef":1},{"term":"Bollinger %B","name":"","def":"Bollinger %B converts where price sits between the upper and lower Bollinger Bands into a coordinate: the lower band is 0, the middle band is 0.5, and the upper band is 1.","path":"learn/23-en.html","title":"Bollinger %B","g":"market","isDef":1},{"term":"Bollinger Bands","name":"","def":"Bollinger Bands plot a recent average price line in the middle, then draw upper and lower bands at a multiple of price standard deviation above and below it.","path":"learn/21-en.html","title":"Bollinger Bands","g":"market","isDef":1},{"term":"Bollinger BandWidth","name":"","def":"Bollinger BandWidth (BBW) turns the distance between the upper and lower Bollinger Bands into a single number, commonly calculated as (Upper Band − Lower Band) ÷ Middle Band × 100.","path":"learn/22-en.html","title":"Bollinger BandWidth","g":"market","isDef":1},{"term":"BOP","name":"","def":"Measure what fraction of a bar's total high-to-low range was retained as net open-to-close progress: Balance of Power (BOP) = (Close − Open) ÷ (High − Low).","path":"learn/85-en.html","title":"BOP","g":"market","isDef":1},{"term":"Breakouts & Failed Breakouts","name":"","def":"A breakout is a bar that closes beyond the prior range high (or low).","path":"learn/131-en.html","title":"Breakouts & Failed Breakouts","g":"market","isDef":1},{"term":"Bridges & Oracles","name":"","def":"A cross-chain bridge “moves” assets between chains, usually by locking them on the source chain and minting an equal amount of wrapped tokens on the destination; if the bridge’s lock contract or signers are compromised, the wrapped tokens can lose their backing.","path":"learn/202-en.html","title":"Bridges & Oracles","g":"web3","isDef":1},{"term":"Building Permits","name":"","def":"Building Permits, published monthly by the U.S. Census Bureau and HUD alongside Housing Starts in the New Residential Construction report, count the number of privately owned new housing units authorized by building permits in permit-issuing jurisdictions during the reference month. They measure pre-construction regulatory approvals and builder intentions—one step ahead of Housing Starts (Lesson 41)—rather than active excavations or finished homes. Beginners often assume a permit means construction has already begun or overlook that non-permit rural areas are excluded from permit counts.","path":"info/learn/42-en.html","title":"Building Permits","g":"info","isDef":1},{"term":"Bull/Bear Power","name":"","def":"Bull/Bear Power subtracts the same EMA from a bar's high and low to measure how far the two extremes of a candlestick reach from the recent average: Bull Power = High − EMA, and Bear Power = Low − EMA.","path":"learn/20-en.html","title":"Bull/Bear Power","g":"market","isDef":1},{"term":"Candlestick Patterns","name":"","def":"Candlestick Patterns read the relationship among Open, High, Low, and Close across one to three bars, helping you answer which side controlled the close and where intraday pushes were rejected during that interval.","path":"learn/113-en.html","title":"Candlestick Patterns","g":"market","isDef":1},{"term":"Capacity Utilization","name":"","def":"Industrial output relative to sustainable capacity: making 78 units out of a sustainable 100 means roughly 78% utilization.","path":"info/learn/28-en.html","title":"Capacity Utilization","g":"info","isDef":1},{"term":"Cboe Volatility Index (VIX)","name":"","def":"Often dubbed the 'Fear Gauge', the VIX is not an opinion poll—it is a mathematical index derived directly from real-time S&P 500 option prices measuring expected 30-day volatility.","path":"info/learn/74-en.html","title":"Cboe Volatility Index (VIX)","g":"info","isDef":1},{"term":"CCI","name":"","def":"The Commodity Channel Index (CCI) measures how far a bar's typical price sits from its recent average, scaled by the average size of normal deviations over that window.","path":"learn/15-en.html","title":"CCI","g":"market","isDef":1},{"term":"Chaikin Oscillator","name":"","def":"Measure the momentum of the Accumulation/Distribution Line (ADL) by subtracting a slower EMA of ADL from a faster EMA of ADL, rather than looking only at the cumulative ADL level.","path":"learn/79-en.html","title":"Chaikin Oscillator","g":"market","isDef":1},{"term":"Chan Theory (Chan Lun)","name":"","def":"Chan Theory (Chanlun) applies a step-by-step geometric hierarchy—candle inclusion merging, top/bottom fractals, strokes, segments, and overlapping centers—helping you answer how price swings organize around and depart from defined overlapping zones.","path":"learn/122-en.html","title":"Chan Theory (Chan Lun)","g":"market","isDef":1},{"term":"Chande Kroll Stop","name":"","def":"Chande Kroll Stop combines recent high-low price extremes and Average True Range (ATR) into two smoothed trailing exit reference lines (Stop Long and Stop Short).","path":"learn/90-en.html","title":"Chande Kroll Stop","g":"market","isDef":1},{"term":"Chandelier Exit","name":"","def":"Chandelier Exit helps a trader who already holds a position frame the question: 'how far below the recent peak (or above the recent trough) can price pull back before I re-examine my thesis?' The standard long exit line subtracts a multiple of Average True Range (ATR—typical single-bar range) from the highest high of the lookback window, leaving a volatility-scaled buffer rather than estimating fair fundamental value.","path":"learn/89-en.html","title":"Chandelier Exit","g":"market","isDef":1},{"term":"Channel Lines & Overshoots","name":"","def":"In a rising channel, the channel line is drawn parallel to the trend line on the side of the highs.","path":"learn/136-en.html","title":"Channel Lines & Overshoots","g":"market","isDef":1},{"term":"China Consumer Price Index (CPI)","name":"","def":"China's Consumer Price Index (CPI) measures retail price changes across a basket of goods and services purchased by urban and rural households.","path":"info/learn/76-en.html","title":"China Consumer Price Index (CPI)","g":"info","isDef":1},{"term":"China Official Manufacturing PMI","name":"","def":"China's Official Manufacturing PMI is the earliest monthly macroeconomic indicator, released on the very last day of the current month.","path":"info/learn/77-en.html","title":"China Official Manufacturing PMI","g":"info","isDef":1},{"term":"Choppiness Index","name":"","def":"Distinguish whether price has been grinding in circles inside a box or traveling smoothly in one net direction.","path":"learn/46-en.html","title":"Choppiness Index","g":"market","isDef":1},{"term":"Classical Chart Patterns","name":"","def":"Classic Chart Patterns group multi-bar swing outlines into shapes such as double tops/bottoms, head-and-shoulders, triangles, and flags, helping you answer how buyers and sellers are consolidating across multiple swings and which boundary break confirms a resolution.","path":"learn/114-en.html","title":"Classical Chart Patterns","g":"market","isDef":1},{"term":"Climaxes & Exhaustion","name":"","def":"A climax is a run of unusually large bars in the trend’s direction at the end of a move, with ranges well above the recent average (here, more than twice the average range of the prior 20 bars), usually on rising volume.","path":"learn/137-en.html","title":"Climaxes & Exhaustion","g":"market","isDef":1},{"term":"Cloud","name":"Kumo","def":"formed by Leading Spans A and B","path":"learn/47-en.html","title":"Ichimoku","g":"market"},{"term":"CMF","name":"","def":"Divide the sum of close-location-weighted volume over a rolling N-bar window by total volume over that same window to see whether volume has tilted toward upper-range or lower-range closes.","path":"learn/78-en.html","title":"CMF","g":"market","isDef":1},{"term":"CMO","name":"","def":"Compare total upward point gains against total downward point losses over a lookback window to see which side accumulated more ground.","path":"learn/59-en.html","title":"CMO","g":"market","isDef":1},{"term":"Commercial Bank Deposits H.8","name":"","def":"Commercial Bank Deposits in the Federal Reserve's weekly H.8 release track total deposit liabilities owed to households and businesses across commercial banks in the United States, serving as a high-frequency gauge of banking-system funding stability.","path":"info/learn/56-en.html","title":"Commercial Bank Deposits H.8","g":"info","isDef":1},{"term":"Commercial Bank Loans H.8","name":"","def":"Commercial Bank Loans and Leases in the Federal Reserve's weekly H.8 release measure the total stock of outstanding credit extended by commercial banks that has not yet been repaid.","path":"info/learn/57-en.html","title":"Commercial Bank Loans H.8","g":"info","isDef":1},{"term":"Concentrated Liquidity & Liquidity Management","name":"","def":"An automated market maker mechanism allowing liquidity providers (LPs) to allocate capital within custom price ranges (ticks) for higher capital efficiency, alongside active range-management strategies.","path":"learn/227-en.html","title":"Concentrated Liquidity & Liquidity Management","g":"web3","isDef":1},{"term":"Conference Board Consumer Confidence Index","name":"","def":"The Conference Board Consumer Confidence Index, published monthly by The Conference Board, surveys U.S. households on their assessment of current business and job conditions as well as their expectations for business, employment, and income over the next six months.","path":"info/learn/37-en.html","title":"Conference Board Consumer Confidence Index","g":"info","isDef":1},{"term":"ConnorsRSI","name":"","def":"Combine short-term RSI momentum, the duration of consecutive up or down closes (streak length), and the percentile rank of today's single-bar percentage return into one composite score to spot short-term price extension.","path":"learn/58-en.html","title":"ConnorsRSI","g":"market","isDef":1},{"term":"Consensus & Chain Types","name":"","def":"A consensus mechanism is the set of rules plus rewards and penalties by which mutually distrustful nodes decide who writes the next block and what counts as valid.","path":"learn/198-en.html","title":"Consensus & Chain Types","g":"web3","isDef":1},{"term":"Consumer Credit G.19","name":"","def":"Consumer Credit (the G.19 statistical release), published monthly by the Federal Reserve Board about five weeks after the reference month, measures outstanding U.S. household debt that is not secured by real estate, split into Revolving credit (mainly credit cards) and Nonrevolving credit (such as auto loans and student loans).","path":"info/learn/39-en.html","title":"Consumer Credit G.19","g":"info","isDef":1},{"term":"Consumer Price Index (CPI)","name":"","def":"Tracks prices paid by urban US consumers for a basket including housing, food, transport and services.","path":"info/learn/1-en.html","title":"Consumer Price Index (CPI)","g":"info","isDef":1},{"term":"Continuing Unemployment Insurance Claims","name":"","def":"Continuing insured claims help assess whether workers remain on unemployment benefits and how easily they may be finding new jobs.","path":"info/learn/17-en.html","title":"Continuing Unemployment Insurance Claims","g":"info","isDef":1},{"term":"Coppock Curve","name":"","def":"Monitor whether long-horizon momentum is beginning to turn up after a deep, prolonged downturn.","path":"learn/74-en.html","title":"Coppock Curve","g":"market","isDef":1},{"term":"Core Capital Goods Orders","name":"","def":"Usually nondefense capital goods orders excluding aircraft, used to assess business equipment demand with less defense and aircraft volatility.","path":"info/learn/30-en.html","title":"Core Capital Goods Orders","g":"info","isDef":1},{"term":"Core CPI","name":"","def":"CPI excluding food and energy helps reveal persistent price pressure behind volatile components.","path":"info/learn/2-en.html","title":"Core CPI","g":"info","isDef":1},{"term":"Core PCE Price Index","name":"","def":"PCE prices excluding food and energy are used to assess persistence.","path":"info/learn/4-en.html","title":"Core PCE Price Index","g":"info","isDef":1},{"term":"Core PPI: Final Demand Less Foods and Energy","name":"","def":"Here core means final demand less foods and energy.","path":"info/learn/6-en.html","title":"Core PPI: Final Demand Less Foods and Energy","g":"info","isDef":1},{"term":"Correlation Coefficient","name":"","def":"Measure whether two series have tended to move up and down together over a recent lookback window.","path":"learn/56-en.html","title":"Correlation Coefficient","g":"market","isDef":1},{"term":"Cost Distribution (Chip Distribution)","name":"","def":"Cost distribution (“chip distribution”) is an estimate: it assumes each day’s trading replaces part of the existing holdings according to turnover, allocates volume across the day’s price range, accumulates it day by day while decaying older “chips”, and arrives at where current holders’ costs are roughly distributed.","path":"learn/162-en.html","title":"Cost Distribution (Chip Distribution)","g":"market","isDef":1},{"term":"Covered Calls & Protective Puts","name":"","def":"A Covered Call combines holding the underlying asset (e.g., 100 shares of stock) with selling 1 corresponding Call option, collecting option premium in exchange for capping upside gains above the strike price—unlike an unhedged naked short call (see the \"Options Basics\" lesson on this site).","path":"learn/212-en.html","title":"Covered Calls & Protective Puts","g":"market","isDef":1},{"term":"Credit Spreads (High-Yield OAS)","name":"","def":"Credit spreads represent the extra default insurance premium that corporate borrowers must pay above risk-free U.S. Treasury yields. Because bondholders prioritize principal survival over upside narratives, credit spreads serve as a vital reality check on equity market rallies.","path":"info/learn/75-en.html","title":"Credit Spreads (High-Yield OAS)","g":"info","isDef":1},{"term":"Cross","name":"Moving Average Crossover","def":"an overlay plotting a shorter, faster moving average alongside a longer, slower moving average","path":"learn/9-en.html","title":"MA Cross","g":"market"},{"term":"Crypto ETF Daily Net Flows","name":"","def":"Crypto ETF Daily Net Flows track the net dollar amount of capital entering or leaving spot cryptocurrency exchange-traded funds (such as spot Bitcoin or Ether ETFs) on each U.S. equity trading day through primary-market share creations minus redemptions.","path":"info/learn/64-en.html","title":"Crypto ETF Daily Net Flows","g":"info","isDef":1},{"term":"Cup and Handle","name":"","def":"Cup and handle: price falls from a high (the rim), forms a rounded bottom (the cup, not a V), and returns near the rim; it then pulls back slightly to form a “handle” whose retracement is less than half the cup’s depth.","path":"learn/154-en.html","title":"Cup and Handle","g":"market","isDef":1},{"term":"Cutting Losses","name":"","def":"Cutting a loss means writing down, before entry, the condition that proves the trade wrong (the invalidation, either a price or a closing condition) and exiting as planned when it happens, rather than delaying because you do not want to admit the loss.","path":"learn/170-en.html","title":"Cutting Losses","g":"market","isDef":1},{"term":"CVD","name":"","def":"Cumulative Volume Delta (CVD) keeps a running ledger of single-bar Volume Delta values over a chosen anchor period to show whether positive-classified or negative-classified volume has been more persistent over time.","path":"learn/102-en.html","title":"CVD","g":"market","isDef":1},{"term":"DAOs & On-Chain Governance","name":"","def":"Decentralized Autonomous Organizations (DAOs), coordination structures that manage shared treasuries and protocol parameters through smart contracts, token voting, timelocks, and multisigs.","path":"learn/230-en.html","title":"DAOs & On-Chain Governance","g":"web3","isDef":1},{"term":"Dark Cloud Cover & Piercing Pattern","name":"","def":"Dark cloud cover: the first bar is a long bullish bar; the second trades above the first bar’s high, then falls back to close as a bearish bar below the midpoint of the first body but above the first open.","path":"learn/147-en.html","title":"Dark Cloud Cover & Piercing Pattern","g":"market","isDef":1},{"term":"Darvas Box","name":"","def":"Darvas box: after price makes a new high, if the next three bars fail to exceed it, that high becomes the box top; once the top is set, if a subsequent low is not broken by the next three bars, that low becomes the box bottom.","path":"learn/165-en.html","title":"Darvas Box","g":"market","isDef":1},{"term":"DeFi Lending & Liquidation","name":"","def":"Decentralized lending protocols such as Aave and Compound let users deposit assets to earn interest or borrow other assets against deposits.","path":"learn/206-en.html","title":"DeFi Lending & Liquidation","g":"web3","isDef":1},{"term":"DEMA","name":"","def":"The Double Exponential Moving Average (DEMA) is plotted as a single composite line on the chart: 2 times the first EMA minus a doubly smoothed EMA (an EMA of the first EMA).","path":"learn/7-en.html","title":"DEMA","g":"market","isDef":1},{"term":"DePIN: Token-Incentivised Infrastructure","name":"","def":"Decentralized Physical Infrastructure Networks (DePIN), a model that uses token incentives to coordinate individuals and nodes worldwide to contribute hardware resources—such as wireless hotspots, sensors, storage, or compute—to build and operate physical infrastructure.","path":"learn/215-en.html","title":"DePIN: Token-Incentivised Infrastructure","g":"web3","isDef":1},{"term":"DeSci: Decentralised Science","name":"","def":"Decentralized Science (DeSci), a movement using blockchains, DAOs, non-transferable credentials, and IP-NFTs to reform research funding, peer review, open data sharing, and intellectual property commercialization.","path":"learn/219-en.html","title":"DeSci: Decentralised Science","g":"web3","isDef":1},{"term":"Deviation","name":"StDev","def":"a statistical gauge calculating the square root of the average squared distance between recent closes and their simple moving average","path":"learn/30-en.html","title":"Standard Deviation","g":"market"},{"term":"DEXs & AMMs","name":"","def":"A decentralized exchange (DEX) lets users trade directly from their own wallets through smart contracts, without handing assets to an exchange.","path":"learn/205-en.html","title":"DEXs & AMMs","g":"web3","isDef":1},{"term":"Discount Window Borrowing Primary Credit","name":"","def":"Discount Window Borrowing (focused primarily on Primary Credit in the Federal Reserve's H.4.1 release) measures short-term collateralized loans extended directly by the Federal Reserve to eligible depository institutions against pledged loans or securities.","path":"info/learn/60-en.html","title":"Discount Window Borrowing Primary Credit","g":"info","isDef":1},{"term":"Disposable Personal Income (DPI)","name":"","def":"Personal income after personal current taxes, available for spending or saving; disposable does not mean after rent and other living expenses.","path":"info/learn/35-en.html","title":"Disposable Personal Income (DPI)","g":"info","isDef":1},{"term":"Divergence","name":"","def":"Regular bearish divergence: price’s second swing high is above the first, while the indicator’s value at that same bar is below its first high; regular bullish divergence is the reverse.","path":"learn/156-en.html","title":"Divergence","g":"market","isDef":1},{"term":"Dividends & Corporate Actions","name":"","def":"Ex-dividend and ex-rights represent the regulatory adjustment of a stock's market trading price following cash dividend distributions, bonus shares, or rights offerings.","path":"learn/187-en.html","title":"Dividends & Corporate Actions","g":"market","isDef":1},{"term":"DMI","name":"","def":"Separate market action into two distinct questions—direction and strength: +DI and −DI compare upward push versus downward pressure, while ADX checks whether that lead is persisting.","path":"learn/42-en.html","title":"DMI","g":"market","isDef":1},{"term":"Donchian","name":"","def":"Donchian Channels plot the highest high and lowest low over the last N bars as the upper and lower bands, with the midpoint between those two extremes as the middle line.","path":"learn/24-en.html","title":"Donchian","g":"market","isDef":1},{"term":"Double Tops & Bottoms","name":"","def":"Double top: two similar swing highs (the second may be slightly higher or lower; here within 1%) with a swing low between them.","path":"learn/149-en.html","title":"Double Tops & Bottoms","g":"market","isDef":1},{"term":"Dow Theory","name":"","def":"Dow Theory separates market movement into three scales—the primary trend (tide), secondary reactions (waves), and minor daily fluctuations (ripples)—while checking whether related averages confirm each other, helping you answer whether a pullback is a normal pause inside a broad trend or a structural reversal.","path":"learn/116-en.html","title":"Dow Theory","g":"market","isDef":1},{"term":"DPO","name":"","def":"Strip out a longer-term moving average trend so you can examine shorter-term high-and-low cycles around that baseline.","path":"learn/70-en.html","title":"DPO","g":"market","isDef":1},{"term":"Dragon-Tiger List","name":"","def":"The Dragon-Tiger List (Statutory Trading Public Information) is an after-hours regulatory disclosure by Chinese stock exchanges listing the top five buying and selling brokerage branches or trading units for securities hitting abnormal thresholds in daily price deviation, amplitude, turnover, or 3-day cumulative deviation.","path":"learn/194-en.html","title":"Dragon-Tiger List","g":"market","isDef":1},{"term":"Durable Goods Orders","name":"","def":"New orders for manufactured goods generally expected to last at least three years, including machinery, vehicles and aircraft.","path":"info/learn/29-en.html","title":"Durable Goods Orders","g":"info","isDef":1},{"term":"Earnings Season & Guidance","name":"","def":"Earnings season is the concentrated period when public companies report periodic financials; Consensus Estimates represent the mean analyst forecast for revenue and EPS; Guidance is management's official forward-looking performance forecast.","path":"learn/186-en.html","title":"Earnings Season & Guidance","g":"market","isDef":1},{"term":"ECB Monetary Policy Decision","name":"","def":"The ECB Monetary Policy Decision, announced eight times a year by the European Central Bank Governing Council on scheduled Thursdays at 14:15 Frankfurt time followed by the President's press conference at 14:45 (with Macroeconomic Staff Projections released in March, June, September, and December), sets official policy interest rates and balance-sheet parameters for the 20-nation euro area.","path":"info/learn/67-en.html","title":"ECB Monetary Policy Decision","g":"info","isDef":1},{"term":"EIA Weekly Crude Oil Inventories","name":"","def":"EIA Weekly Crude Oil Inventories, published every Wednesday at 10:30 a.m.","path":"info/learn/70-en.html","title":"EIA Weekly Crude Oil Inventories","g":"info","isDef":1},{"term":"EIA Weekly Natural Gas Storage","name":"","def":"The EIA Weekly Natural Gas Storage Report, published every Thursday at 10:30 a.m.","path":"info/learn/71-en.html","title":"EIA Weekly Natural Gas Storage","g":"info","isDef":1},{"term":"Elder Force Index","name":"","def":"Combine the size of a bar-to-bar closing price change with the trading volume on that bar: the larger the price change and the heavier the volume, the larger the Force Index reading.","path":"learn/81-en.html","title":"Elder Force Index","g":"market","isDef":1},{"term":"Elliott Wave Theory","name":"","def":"Elliott Wave Theory classifies trend-following moves into 5-wave impulses (waves 1, 3, 5 with the trend and 2, 4 against it) and counter-trend moves into 3-wave corrections (A, B, C), helping you answer which exact price level would falsify your current wave hypothesis.","path":"learn/117-en.html","title":"Elliott Wave Theory","g":"market","isDef":1},{"term":"EMA","name":"","def":"The Exponential Moving Average (EMA) also organizes prices into an average line, but assigns greater weight to the most recent closing prices, so it typically turns faster than an SMA of the same bar length.","path":"learn/2-en.html","title":"EMA","g":"market","isDef":1},{"term":"Employment Cost Index (ECI)","name":"","def":"Measures changes in hourly employer compensation, including wages and benefits, while controlling for shifts in the mix of jobs.","path":"info/learn/9-en.html","title":"Employment Cost Index (ECI)","g":"info","isDef":1},{"term":"Engulfing Patterns","name":"","def":"Bullish engulfing: the prior bar is bearish, the current bar is bullish, and the current body fully covers the prior body (it opens at or below the prior close and closes above the prior open).","path":"learn/140-en.html","title":"Engulfing Patterns","g":"market","isDef":1},{"term":"EOM/EMV","name":"","def":"Compare how far a bar's high-low midpoint moved against the bar's high-low range and trading volume to see whether price moved a given distance on relatively light or heavy volume.","path":"learn/82-en.html","title":"EOM/EMV","g":"market","isDef":1},{"term":"Everyday Tools & Industry Jargon","name":"","def":"The five essential tool categories for daily Web3 research and operations (block explorers, data dashboards, self-custody wallets, multisigs, and testnet faucets) alongside core industry jargon.","path":"learn/221-en.html","title":"Everyday Tools & Industry Jargon","g":"web3","isDef":1},{"term":"Exchange Risk: Lessons from Mt. Gox, FTX & Bybit","name":"","def":"A centralized exchange (CEX) holds users’ assets and matches trades internally: the balance you see is a debt the exchange owes you, not coins in your own on-chain wallet.","path":"learn/199-en.html","title":"Exchange Risk: Lessons from Mt. Gox, FTX & Bybit","g":"web3","isDef":1},{"term":"Exchanges, Brokers & Trading Rules","name":"","def":"An exchange matches buyers and sellers (for example the NYSE, Nasdaq, and the Shanghai and Shenzhen exchanges); ordinary investors open an account with a broker to place orders.","path":"learn/176-en.html","title":"Exchanges, Brokers & Trading Rules","g":"market","isDef":1},{"term":"Existing-Home Sales","name":"","def":"Existing-Home Sales, published monthly by the National Association of Realtors (NAR), count the number of previously owned U.S. homes (single-family homes, townhomes, condominiums, and co-ops) where sales transactions officially closed (title transferred) during the reference month, alongside active inventory and median sales prices.","path":"info/learn/43-en.html","title":"Existing-Home Sales","g":"info","isDef":1},{"term":"Expectancy & Win Rate","name":"","def":"Expectancy (average result per trade) = win rate × average win − (1 − win rate) × average loss, with the average loss taken as a positive number.","path":"learn/172-en.html","title":"Expectancy & Win Rate","g":"market","isDef":1},{"term":"Export Price Index","name":"","def":"Tracks dollar prices of US exports of goods and selected services.","path":"info/learn/8-en.html","title":"Export Price Index","g":"info","isDef":1},{"term":"Federal Reserve Balance Sheet","name":"","def":"The Federal Reserve Balance Sheet (officially the H.4.1 statistical release, 'Factors Affecting Reserve Balances'), published every Thursday at 4:30 p.m.","path":"info/learn/51-en.html","title":"Federal Reserve Balance Sheet","g":"info","isDef":1},{"term":"Federal Reserve FOMC Rate Decision","name":"","def":"The Federal Reserve FOMC Rate Decision, announced eight times a year on scheduled Wednesdays at 2:00 p.m.","path":"info/learn/66-en.html","title":"Federal Reserve FOMC Rate Decision","g":"info","isDef":1},{"term":"FHFA House Price Index","name":"","def":"The FHFA House Price Index (FHFA HPI), published monthly and quarterly by the Federal Housing Finance Agency, uses a repeat-sales methodology to track single-family home price changes across mortgages acquired or assured by Fannie Mae and Freddie Mac.","path":"info/learn/47-en.html","title":"FHFA House Price Index","g":"info","isDef":1},{"term":"Fibonacci","name":"","def":"Fibonacci Retracements and Extensions divide a completed price swing into standard ratios, helping you answer how much of a prior move price has retraced or how far an extension projects relative to that move.","path":"learn/96-en.html","title":"Fibonacci","g":"market","isDef":1},{"term":"Fisher Transform","name":"","def":"Apply the inverse hyperbolic tangent (Fisher Transform) to a normalized range-location series so that readings near the outer edges of a recent high-low window are stretched out into sharp, clearly visible peaks and troughs.","path":"learn/69-en.html","title":"Fisher Transform","g":"market","isDef":1},{"term":"Flags & Pennants","name":"","def":"A flag starts with a sharp “pole” (a few large bars), followed by a small parallel channel sloping against the pole (the flag) that retraces no more than half the pole.","path":"learn/151-en.html","title":"Flags & Pennants","g":"market","isDef":1},{"term":"Freddie Mac Primary Mortgage Market Survey PMMS","name":"","def":"The Freddie Mac Primary Mortgage Market Survey (PMMS), published every Thursday at noon Eastern by Freddie Mac, reports the weekly U.S. national average interest rate on the benchmark 30-Year Fixed-Rate Mortgage (and 15-Year Fixed-Rate Mortgage).","path":"info/learn/49-en.html","title":"Freddie Mac Primary Mortgage Market Survey PMMS","g":"info","isDef":1},{"term":"Funding Rate","name":"","def":"The Funding Rate shows the periodic fee percentage exchanged between long and short perpetual contract holders (commonly every 8 hours), helping you answer whether the perpetual trades rich or cheap relative to spot and which side pays to hold positions across the settlement timestamp.","path":"learn/108-en.html","title":"Funding Rate","g":"market","isDef":1},{"term":"GameFi: On-Chain Game Economies","name":"","def":"The integration of blockchain asset ownership and decentralized finance mechanics into video games, enabling in-game items, characters, and currencies to be held and traded on-chain.","path":"learn/228-en.html","title":"GameFi: On-Chain Game Economies","g":"web3","isDef":1},{"term":"Gann Theory","name":"","def":"Gann Tools (such as the Gann Fan and Gann Box) link price change and elapsed time bars into fixed-ratio diagonal lines, helping you answer whether price is advancing faster or slower than a chosen baseline pace (the 1×1 line).","path":"learn/121-en.html","title":"Gann Theory","g":"market","isDef":1},{"term":"Gaps","name":"","def":"An up gap is when a bar’s low is above the prior bar’s high, leaving a price zone with no trading between them; a down gap is the reverse.","path":"learn/138-en.html","title":"Gaps","g":"market","isDef":1},{"term":"Greeks I: Delta & Gamma","name":"","def":"Delta (Δ) measures how much an option's theoretical price changes for a 1-unit move in the underlying asset; Call Delta ranges from 0 to 1, while Put Delta ranges from -1 to 0.","path":"learn/208-en.html","title":"Greeks I: Delta & Gamma","g":"market","isDef":1},{"term":"Greeks II: Theta & Vega","name":"","def":"Theta (Θ) measures the daily decline in an option's theoretical value due purely to the passage of one calendar day, holding other inputs constant (typically negative for option buyers).","path":"learn/209-en.html","title":"Greeks II: Theta & Vega","g":"market","isDef":1},{"term":"Hammer & Hanging Man","name":"","def":"Shape: a lower shadow at least twice the body, a short upper shadow (no longer than the body), and the body in the upper part of the range.","path":"learn/141-en.html","title":"Hammer & Hanging Man","g":"market","isDef":1},{"term":"Harami","name":"","def":"Harami: the second bar’s body lies entirely within the first bar’s body (touching the edge counts), the second body is less than half the first, and the two usually have opposite colours.","path":"learn/146-en.html","title":"Harami","g":"market","isDef":1},{"term":"Harmonic Patterns","name":"","def":"Harmonic Patterns measure Fibonacci retracement and extension ratios across five swing points and four legs (X-A-B-C-D), helping you answer whether a four-leg swing sequence matches a specific geometric template (such as a Gartley or Bat) and where its Potential Reversal Zone (PRZ) sits.","path":"learn/119-en.html","title":"Harmonic Patterns","g":"market","isDef":1},{"term":"Head & Shoulders","name":"","def":"Head and shoulders top: of three swing highs, the middle “head” is higher than the left and right “shoulders”; the two lows between them define the neckline.","path":"learn/148-en.html","title":"Head & Shoulders","g":"market","isDef":1},{"term":"Heikin Ashi","name":"","def":"Heikin Ashi recalculates each bar: HA close = (open + high + low + close) ÷ 4; HA open = (prior HA open + prior HA close) ÷ 2; HA high = the maximum of the real high, HA open and HA close; HA low is the minimum.","path":"learn/159-en.html","title":"Heikin Ashi","g":"market","isDef":1},{"term":"Historical Volatility","name":"","def":"Historical Volatility (HV) measures how unstable bar-to-bar percentage returns have been over a recent lookback window, usually scaled into an annualized percentage.","path":"learn/31-en.html","title":"Historical Volatility","g":"market","isDef":1},{"term":"HMA","name":"","def":"The Hull Moving Average (HMA) combines several weighted moving averages to keep the line smooth while reducing lag as much as possible.","path":"learn/6-en.html","title":"HMA","g":"market","isDef":1},{"term":"Household Loan Delinquency Rates","name":"","def":"Household Loan Delinquency Rates, published quarterly by the Federal Reserve Board (from commercial bank regulatory filings) and supplemented by the New York Fed's Quarterly Report on Household Debt and Credit, measure the percentage of loan balances in credit cards, auto loans, consumer loans, and residential mortgages that are past due.","path":"info/learn/40-en.html","title":"Household Loan Delinquency Rates","g":"info","isDef":1},{"term":"Housing Starts","name":"","def":"Housing Starts, published monthly by the U.S. Census Bureau and the Department of Housing and Urban Development (HUD) in the New Residential Construction report, count the number of privately owned new housing units where excavation (groundbreaking) actually began during the reference month. It measures physical construction starts rather than pre-construction permits or completed home sales. Beginners often misread a headline '1.40 million Seasonally Adjusted Annual Rate' as meaning 1.40 million homes broke ground in that single month.","path":"info/learn/41-en.html","title":"Housing Starts","g":"info","isDef":1},{"term":"Ichimoku","name":"","def":"View near-term equilibrium, medium-term equilibrium, and a broader support/resistance zone on a single chart.","path":"learn/47-en.html","title":"Ichimoku","g":"market","isDef":1},{"term":"Implied Volatility, IV Rank & Volatility Crush","name":"","def":"Implied Volatility (IV) is the annualized expected volatility backed out from an option's live market price using a pricing model.","path":"learn/210-en.html","title":"Implied Volatility, IV Rank & Volatility Crush","g":"market","isDef":1},{"term":"Import Price Index","name":"","def":"Tracks dollar prices of US imports of goods and selected services, helping identify external cost pressure.","path":"info/learn/7-en.html","title":"Import Price Index","g":"info","isDef":1},{"term":"Index","name":"CHOP","def":"a gauge of sideways overlap versus directional efficiency","path":"learn/46-en.html","title":"Choppiness Index","g":"market","more":[{"path":"learn/60-en.html","title":"True Strength Index"},{"path":"learn/66-en.html","title":"Relative Vigor Index"},{"path":"learn/68-en.html","title":"RCI"}]},{"term":"Indexes & ETFs","name":"","def":"A stock index turns the prices of a basket of stocks into one number representing a market or sector, such as the S&P 500, the Nasdaq-100 or the CSI 300.","path":"learn/178-en.html","title":"Indexes & ETFs","g":"market","isDef":1},{"term":"Indicators","name":"McClellan Oscillator","def":"Advance Decline Line, Arms Index TRIN","path":"learn/104-en.html","title":"Advance/Decline","g":"market"},{"term":"Industrial Production Index","name":"","def":"Measures real output from manufacturing, mining and utilities, rather than the full service-heavy US economy.","path":"info/learn/27-en.html","title":"Industrial Production Index","g":"info","isDef":1},{"term":"Initial Unemployment Insurance Claims","name":"","def":"New applications for unemployment insurance during a week, a timely indicator of layoff pressure but not a count of all newly unemployed people.","path":"info/learn/16-en.html","title":"Initial Unemployment Insurance Claims","g":"info","isDef":1},{"term":"Inner Circle Trader (ICT)","name":"","def":"The ICT methodology combines specific New York session windows (Killzones), prior session highs/lows, and three-candle Fair Value Gaps (FVG) into a rule-based routine, helping you answer whether price swept a key high or low during an active session window and displaced sharply in the opposite direction.","path":"learn/124-en.html","title":"Inner Circle Trader (ICT)","g":"market","isDef":1},{"term":"Inside & Outside Bars","name":"","def":"An inside bar has a high below the previous high and a low above the previous low; an outside bar has a high above the previous high and a low below the previous low.","path":"learn/129-en.html","title":"Inside & Outside Bars","g":"market","isDef":1},{"term":"Interest","name":"OI","def":"a derivatives statistic counting the total number of futures or perpetual contracts that remain open and unsettled at the end of each bar","path":"learn/107-en.html","title":"Open Interest","g":"market"},{"term":"Inventory","name":"Houses for Sale—including completed homes","def":"homes under construction, and permitted units not yet started","path":"info/learn/44-en.html","title":"New Residential Sales","g":"info"},{"term":"IPOs & New Listings","name":"","def":"An Initial Public Offering (IPO) is the initial sale of equity by a private corporation to the institutional and retail public.","path":"learn/188-en.html","title":"IPOs & New Listings","g":"market","isDef":1},{"term":"ISM Manufacturing PMI","name":"","def":"A diffusion survey of manufacturing purchasing managers covering orders, production, employment and related conditions; 50 marks no change for the surveyed sector.","path":"info/learn/23-en.html","title":"ISM Manufacturing PMI","g":"info","isDef":1},{"term":"ISM Services PMI","name":"","def":"Surveys service-sector purchasing managers on activity, orders, employment and deliveries, informing broad demand and service-price pressure.","path":"info/learn/24-en.html","title":"ISM Services PMI","g":"info","isDef":1},{"term":"JOLTS Job Openings","name":"","def":"Positions open on the final business day of the month, available to start within 30 days and actively being recruited for; demand, not completed hiring.","path":"info/learn/18-en.html","title":"JOLTS Job Openings","g":"info","isDef":1},{"term":"JOLTS Quits Rate","name":"","def":"Voluntary quits as a percentage of employment, often used to gauge willingness to change jobs rather than layoffs.","path":"info/learn/19-en.html","title":"JOLTS Quits Rate","g":"info","isDef":1},{"term":"KAMA","name":"","def":"Observe an adaptive moving average that changes its smoothing speed based on how directional or choppy recent price action has been.","path":"learn/49-en.html","title":"KAMA","g":"market","isDef":1},{"term":"Keltner","name":"","def":"Modern Keltner Channels typically use an EMA as the middle line and set the upper and lower bands at a multiple of Average True Range (ATR) above and below that EMA.","path":"learn/25-en.html","title":"Keltner","g":"market","isDef":1},{"term":"Klinger Oscillator","name":"","def":"Combine trading volume with typical-price direction and high-low range changes into a 'Volume Force' series, then subtract a slower EMA from a faster EMA of that series to track the rhythm of volume-price push.","path":"learn/80-en.html","title":"Klinger Oscillator","g":"market","isDef":1},{"term":"KST","name":"","def":"Combine smoothed rates of change (ROC) across four different lookback lengths into a single momentum curve to reduce the blind spots of watching only one timeframe window.","path":"learn/71-en.html","title":"KST","g":"market","isDef":1},{"term":"Labor Force Participation Rate","name":"","def":"The labor force as a share of the civilian noninstitutional population aged 16 and over: how many people are working or seeking work.","path":"info/learn/13-en.html","title":"Labor Force Participation Rate","g":"info","isDef":1},{"term":"Layer 2 & Rollups","name":"","def":"A layer 2 executes many transactions off the main chain and posts compressed results and proofs back to it (layer 1), cutting fees and raising speed while inheriting as much of the main chain’s security as possible.","path":"learn/201-en.html","title":"Layer 2 & Rollups","g":"web3","isDef":1},{"term":"Limit-up Boards","name":"","def":"A Limit-Up Board occurs when a security hits the maximum daily percentage price increase permitted by the stock exchange; Limit-Up Price = Round(Prior Close * (1 + Limit Percentage), Tick Size).","path":"learn/195-en.html","title":"Limit-up Boards","g":"market","isDef":1},{"term":"Line","name":"ADL","def":"a running total of volume weighted by where the close sits within each bar's high-low range","path":"learn/77-en.html","title":"Accumulation/Distribution","g":"market","more":[{"path":"learn/104-en.html","title":"Advance/Decline"}]},{"term":"Linear Regression Channel","name":"","def":"Separate the overall straight-line direction of recent prices from how far current price sits to either side of that centerline.","path":"learn/53-en.html","title":"Linear Regression Channel","g":"market","isDef":1},{"term":"Linear Regression R²","name":"","def":"Check how well a straight line actually summarizes recent prices.","path":"learn/55-en.html","title":"Linear Regression R²","g":"market","isDef":1},{"term":"Linear Regression Slope","name":"","def":"Quantify the upward or downward tilt of a best-fit straight line through recent prices to see whether directional speed is changing.","path":"learn/54-en.html","title":"Linear Regression Slope","g":"market","isDef":1},{"term":"Liquidations","name":"","def":"Liquidations data records the volume or dollar value of leveraged positions forcefully closed by an exchange's risk engine after margin fell below maintenance requirements, helping you answer how much forced position unwinding accompanied a recent price move.","path":"learn/110-en.html","title":"Liquidations","g":"market","isDef":1},{"term":"Liquidity & Market Impact","name":"","def":"Liquidity is the ability to buy or sell a given quantity without moving the price much, commonly gauged by the bid–ask spread, order-book depth and volume.","path":"learn/174-en.html","title":"Liquidity & Market Impact","g":"market","isDef":1},{"term":"LLC","name":"ICE BofA Indices","def":"published via St. Louis Fed FRED","path":"info/learn/75-en.html","title":"Credit Spreads (High-Yield OAS)","g":"info"},{"term":"Loan Prime Rate (LPR)","name":"","def":"When headlines report an 'interest rate cut' in China, they may refer to PBOC wholesale policy rates (like the 7-Day Reverse Repo) or the retail lending benchmark—the Loan Prime Rate (LPR).","path":"info/learn/79-en.html","title":"Loan Prime Rate (LPR)","g":"info","isDef":1},{"term":"Long/Short Accounts Ratio","name":"","def":"The Long/Short Accounts Ratio divides the number of net-long user accounts by the number of net-short user accounts within a defined platform sample, helping you answer whether more individual accounts are positioned long or short.","path":"learn/109-en.html","title":"Long/Short Accounts Ratio","g":"market","isDef":1},{"term":"LSMA","name":"","def":"See where the right-hand endpoint of a best-fit straight line through recent prices lands today.","path":"learn/52-en.html","title":"LSMA","g":"market","isDef":1},{"term":"M2 Money Stock","name":"","def":"M2 Money Stock is a broad monetary aggregate published by the Federal Reserve that sums transaction money immediately available for spending (M1, including currency outside banks, demand deposits, and savings deposits) together with near-money assets easily convertible into cash (small-denomination time deposits under $100,000 and retail money market fund shares).","path":"info/learn/55-en.html","title":"M2 Money Stock","g":"info","isDef":1},{"term":"MA Cross","name":"","def":"A Moving Average Cross (MA Cross) plots a shorter-term average price alongside a longer-term average price to compare whether recent prices are stronger or weaker than the broader backdrop.","path":"learn/9-en.html","title":"MA Cross","g":"market","isDef":1},{"term":"MACD","name":"","def":"MACD subtracts a slower EMA from a faster EMA to form the MACD line, then smooths that difference with a signal line; the histogram bars show the remaining gap between those two lines.","path":"learn/12-en.html","title":"MACD","g":"market","isDef":1},{"term":"MACD-V","name":"","def":"Normalize the spread between a fast EMA and a slow EMA by dividing by Average True Range (ATR) so you can measure momentum in units of typical bar volatility.","path":"learn/75-en.html","title":"MACD-V","g":"market","isDef":1},{"term":"Margin Financing Balance","name":"","def":"Margin Financing and Securities Lending Balance represents the outstanding aggregate value of borrowed funds used to purchase securities (margin financing) plus borrowed securities sold short (securities lending).","path":"learn/193-en.html","title":"Margin Financing Balance","g":"market","isDef":1},{"term":"Market Structure Analysis","name":"","def":"Market Structure Analysis tracks the sequence of swing highs (HH/LH) and swing lows (HL/LL) on a chosen timeframe, helping you answer whether the trend staircase is extending in the same direction (Break of Structure, BOS) or whether the latest step has been broken.","path":"learn/120-en.html","title":"Market Structure Analysis","g":"market","isDef":1},{"term":"Mass Index","name":"","def":"Track whether the high-to-low range of candlesticks is widening sharply and then starting to contract.","path":"learn/76-en.html","title":"Mass Index","g":"market","isDef":1},{"term":"MBA Weekly Mortgage Applications","name":"","def":"The MBA Weekly Mortgage Applications Survey, published every Wednesday morning by the Mortgage Bankers Association, tracks weekly changes in the volume of single-family mortgage loan applications submitted to U.S. commercial banks, thrifts, and mortgage bankers during the week ended the prior Friday.","path":"info/learn/48-en.html","title":"MBA Weekly Mortgage Applications","g":"info","isDef":1},{"term":"McGinley Dynamic","name":"","def":"Use a dynamic line whose tracking speed adjusts to its ratio with current price to read overall direction and deviation.","path":"learn/51-en.html","title":"McGinley Dynamic","g":"market","isDef":1},{"term":"Measured Moves","name":"","def":"A measured move copies the price distance of the first leg (A to B) from the end of the pullback C in the same direction, giving a reference level D = C + (B − A) for a rise, or D = C − (A − B) for a fall.","path":"learn/135-en.html","title":"Measured Moves","g":"market","isDef":1},{"term":"MFI","name":"","def":"The Money Flow Index (MFI) combines bar-to-bar changes in typical price with trading volume and converts them into a score between 0 and 100.","path":"learn/19-en.html","title":"MFI","g":"market","isDef":1},{"term":"Momentum","name":"","def":"The standard difference version of Momentum (MTM) subtracts the close N bars ago from the current close, directly showing how many dollars or yuan price has moved over that span.","path":"learn/17-en.html","title":"Momentum","g":"market","isDef":1},{"term":"Monthly Treasury Budget Balance","name":"","def":"The Monthly Treasury Budget Balance (from the Monthly Treasury Statement, MTS) measures the difference between total federal government outlays (spending) and total receipts (primarily individual and corporate income taxes and social insurance taxes) over a given month or fiscal year: outlays exceeding receipts produce a budget deficit, while receipts exceeding outlays produce a budget surplus.","path":"info/learn/63-en.html","title":"Monthly Treasury Budget Balance","g":"info","isDef":1},{"term":"Morning & Evening Stars","name":"","def":"Morning star: the first bar is a long bearish bar; the second is a “star” whose body is less than a third of the first body; the third is bullish and closes above the midpoint of the first body.","path":"learn/144-en.html","title":"Morning & Evening Stars","g":"market","isDef":1},{"term":"Moving Average Alignment","name":"","def":"Bullish alignment: the short moving average is above the medium, and the medium above the long (such as MA5 > MA10 > MA20), with all three rising; bearish alignment is the reverse.","path":"learn/168-en.html","title":"Moving Average Alignment","g":"market","isDef":1},{"term":"Moving Average Envelopes","name":"","def":"Moving Average Envelopes plot a moving average as the center line and shift it up and down by a fixed percentage to form upper and lower bands.","path":"learn/26-en.html","title":"Moving Average Envelopes","g":"market","isDef":1},{"term":"Moving Average Ribbon","name":"","def":"A Moving Average Ribbon plots a bundle of moving averages of progressive lengths on the same chart so you can see whether short-, medium-, and longer-term price directions align.","path":"learn/10-en.html","title":"Moving Average Ribbon","g":"market","isDef":1},{"term":"Multi-timeframe Analysis","name":"","def":"Multi-timeframe analysis uses a higher timeframe to set the context (trend direction and key levels) and a lower timeframe to watch how price behaves at those levels.","path":"learn/139-en.html","title":"Multi-timeframe Analysis","g":"market","isDef":1},{"term":"NAHB/Wells Fargo Housing Market Index HMI","name":"","def":"The NAHB/Wells Fargo Housing Market Index (HMI), published monthly (typically mid-month) by the National Association of Home Builders, surveys U.S. single-family homebuilders on their ratings of current new-home sales, sales expectations over the next six months, and traffic of prospective buyers.","path":"info/learn/50-en.html","title":"NAHB/Wells Fargo Housing Market Index HMI","g":"info","isDef":1},{"term":"Net Marketable Treasury Borrowing","name":"","def":"Net Marketable Treasury Borrowing measures the net new funding the U.S. Treasury raises from the private market over a given period by taking gross issuance of marketable Treasury securities and subtracting the principal of maturing securities repaid during the same window. While gross Treasury issuance runs into tens of trillions of dollars annually, the vast majority simply refinances (rolls over) maturing debt; only net borrowing represents incremental new supply that investors must absorb.","path":"info/learn/62-en.html","title":"Net Marketable Treasury Borrowing","g":"info","isDef":1},{"term":"New Highs/New Lows","name":"","def":"New Highs–New Lows counts how many stocks inside a defined universe reached a new high over a specified lookback period (commonly 52 weeks) versus how many reached a new low over that same period.","path":"learn/105-en.html","title":"New Highs/New Lows","g":"market","isDef":1},{"term":"New Residential Sales","name":"","def":"New Residential Sales (commonly called New Home Sales), published monthly by the U.S. Census Bureau and HUD, count the number of newly built privately owned single-family homes sold at the stage of signing a sales contract or accepting a buyer deposit, along with for-sale inventory and sale prices. Although new homes represent only roughly 10%–15% of total U.S. residential transactions, counting sales at contract signing makes this series 1 to 2 months timelier than closing-based Existing-Home Sales (Lesson 43). Beginners often overlook that it covers only single-family houses (excluding condos) and carries wide monthly sampling error.","path":"info/learn/44-en.html","title":"New Residential Sales","g":"info","isDef":1},{"term":"New Token Standards: ERC-404, 6551, 3525","name":"","def":"Emerging token architectures building upon ERC-20 and ERC-721 to explore hybrid fungible/non-fungible liquidity (ERC-404), Token Bound Accounts (ERC-6551), and semi-fungible financial instruments (ERC-3525).","path":"learn/217-en.html","title":"New Token Standards: ERC-404, 6551, 3525","g":"web3","isDef":1},{"term":"Nonfarm Payroll Employment","name":"","def":"Counts jobs on nonfarm establishment payrolls.","path":"info/learn/11-en.html","title":"Nonfarm Payroll Employment","g":"info","isDef":1},{"term":"NVI","name":"","def":"Isolate and accumulate price performance strictly on bars where trading volume was lower than the prior bar's volume.","path":"learn/84-en.html","title":"NVI","g":"market","isDef":1},{"term":"OBV","name":"","def":"On-Balance Volume (OBV) keeps a running score of volume based on bar-to-bar closing direction: if a bar closes higher than the prior close, its entire volume is added; if it closes lower, its entire volume is subtracted; if unchanged, OBV stays flat.","path":"learn/34-en.html","title":"OBV","g":"market","isDef":1},{"term":"On-Chain Derivatives","name":"","def":"Derivatives protocols deployed on smart contracts or app-chains that primarily offer perpetual futures with self-custodial margin and transparent on-chain liquidation rules.","path":"learn/224-en.html","title":"On-Chain Derivatives","g":"web3","isDef":1},{"term":"On-Chain Identity: DID & SBT","name":"","def":"Decentralized Identifiers (DIDs) are cryptographic digital identity standards controlled directly by the user, while Soulbound Tokens (SBTs) are non-transferable on-chain tokens bound to an account to represent credentials, reputation, or affiliations.","path":"learn/216-en.html","title":"On-Chain Identity: DID & SBT","g":"web3","isDef":1},{"term":"Open Interest","name":"","def":"Open Interest (OI) counts the total number of derivative contracts (futures or perpetuals) that remain open and unsettled at a given moment, helping you answer whether total market positioning is expanding (new positions opening) or contracting (existing positions closing).","path":"learn/107-en.html","title":"Open Interest","g":"market","isDef":1},{"term":"Operations & Business Roles in Web3","name":"","def":"The non-technical career landscape in Web3 encompassing community management, user growth, content and research, ecosystem business development (BD), and governance operations.","path":"learn/223-en.html","title":"Operations & Business Roles in Web3","g":"web3","isDef":1},{"term":"Options Basics","name":"","def":"An option is a standardized derivative contract conveying the right, but not the obligation, to buy (Call) or sell (Put) an underlying asset at a designated strike price on or before a specified expiration date.","path":"learn/189-en.html","title":"Options Basics","g":"market","isDef":1},{"term":"Order Book Depth & Liquidity Heatmaps","name":"","def":"Order book depth lists the resting buy and sell orders at each price; a liquidity heatmap plots those resting orders over time as colours, brighter where more size rests.","path":"learn/164-en.html","title":"Order Book Depth & Liquidity Heatmaps","g":"market","isDef":1},{"term":"Order Flow Analysis","name":"","def":"Order Flow Analysis separates executed trades (Time & Sales / Tape) from resting limit orders waiting in the order book (DOM / Depth of Market), helping you answer whether orders at a key price level are actually being consumed by trades or simply pulled (canceled) before execution.","path":"learn/125-en.html","title":"Order Flow Analysis","g":"market","isDef":1},{"term":"Oscillator","name":"KD","def":"an indicator measuring where the current close sits as a percentage of the recent N-bar high-to-low range","path":"learn/13-en.html","title":"Stochastic/KD","g":"market","more":[{"path":"learn/62-en.html","title":"Ultimate Oscillator"},{"path":"learn/63-en.html","title":"Awesome Oscillator/AO"}]},{"term":"Overnight Reverse Repurchase Facility ON RRP","name":"","def":"The Overnight Reverse Repurchase Facility (ON RRP), published every U.S. business day around 1:15 p.m.","path":"info/learn/53-en.html","title":"Overnight Reverse Repurchase Facility ON RRP","g":"info","isDef":1},{"term":"Parabolic SAR","name":"","def":"Parabolic SAR plots a series of dots either below or above price bars, following a step-up acceleration formula to trail the algorithm's current directional state.","path":"learn/38-en.html","title":"Parabolic SAR","g":"market","isDef":1},{"term":"PCE Price Index","name":"","def":"Measures prices associated with household consumption, with coverage and weights differing from CPI, including some healthcare paid on households’ behalf.","path":"info/learn/3-en.html","title":"PCE Price Index","g":"info","isDef":1},{"term":"Pending Home Sales Index","name":"","def":"The Pending Home Sales Index (PHS), published monthly by the National Association of Realtors (NAR), tracks existing-home transactions where a purchase contract has been signed during the reference month but the deal has not yet closed.","path":"info/learn/45-en.html","title":"Pending Home Sales Index","g":"info","isDef":1},{"term":"Percent Above MA","name":"","def":"Percent of Stocks Above Moving Average measures what percentage of stocks inside a defined universe are currently trading above their own individual N-day moving average (for example, each stock's own 200-day simple moving average).","path":"learn/106-en.html","title":"Percent Above MA","g":"market","isDef":1},{"term":"Personal Income","name":"","def":"Income received by persons from earnings, property and transfers, helping assess whether spending has support beyond borrowing.","path":"info/learn/34-en.html","title":"Personal Income","g":"info","isDef":1},{"term":"Personal Saving Rate","name":"","def":"The Personal Saving Rate, published monthly by the U.S. Bureau of Economic Analysis (BEA) within the Personal Income and Outlays report, measures the percentage of disposable personal income (after-tax income) remaining after households pay for personal consumption expenditures, non-mortgage interest, and current transfer payments. It captures the monthly flow ratio of unspent income across the entire U.S. household sector rather than cumulative cash sitting in bank accounts. Beginners often misread it as bank deposit growth or assume stock and home price appreciation boosts the saving rate.","path":"info/learn/36-en.html","title":"Personal Saving Rate","g":"info","isDef":1},{"term":"Phishing Signatures, Address Poisoning & Fake Airdrops","name":"","def":"On-chain phishing does not ask for your money directly.","path":"learn/232-en.html","title":"Phishing Signatures, Address Poisoning & Fake Airdrops","g":"web3","isDef":1},{"term":"Pig Butchering, Rug Pulls & Ponzi Schemes","name":"","def":"Three scams sold as “investments”: pig butchering (building a relationship or trust online, then steering you to a fake platform where your balance keeps rising but cannot be withdrawn); rug pulls (the team raises money or pumps the price, then pulls the liquidity, mints new tokens or blocks selling, and disappears); and Ponzi schemes (paying earlier participants’ “returns” with later participants’ money, kept alive by recruiting, collapsing once new money stops).","path":"learn/233-en.html","title":"Pig Butchering, Rug Pulls & Ponzi Schemes","g":"web3","isDef":1},{"term":"Pin Bars","name":"","def":"A pin bar is a single candle whose main shadow is more than twice its body, with the body near one end of the range and a short or absent opposite shadow; a bullish pin bar has a long lower shadow and a body near the top, while a bearish pin bar has a long upper shadow and a body near the bottom.","path":"learn/130-en.html","title":"Pin Bars","g":"market","isDef":1},{"term":"Pivot Points","name":"","def":"Pivot Points Standard uses the completed high, low, and close of the prior period (such as yesterday, last week, or last month) to plot a set of horizontal reference lines across the current period: P is the central pivot, R1/R2/etc. are upper formula levels, and S1/S2/etc. are lower formula levels.","path":"learn/94-en.html","title":"Pivot Points","g":"market","isDef":1},{"term":"Pivot Points High/Low","name":"","def":"Pivot Points High/Low labels local price peaks and valleys across a chart.","path":"learn/95-en.html","title":"Pivot Points High/Low","g":"market","isDef":1},{"term":"Placing Orders: Market vs Limit","name":"","def":"A market order fills immediately at the best price available, guaranteeing execution but not price.","path":"learn/177-en.html","title":"Placing Orders: Market vs Limit","g":"market","isDef":1},{"term":"PMO","name":"","def":"Observe 1-bar percentage price changes after two layers of custom exponential smoothing to see whether smoothed relative momentum is positive, negative, or slowing down.","path":"learn/73-en.html","title":"PMO","g":"market","isDef":1},{"term":"Point & Figure Charts","name":"","def":"A point and figure chart records rises as columns of X and declines as columns of O, each box worth a fixed price amount (the box size).","path":"learn/161-en.html","title":"Point & Figure Charts","g":"market","isDef":1},{"term":"PPO","name":"","def":"The Percentage Price Oscillator (PPO) divides the difference between a fast EMA and a slow EMA by the slow EMA, expressing their spread as a percentage.","path":"learn/18-en.html","title":"PPO","g":"market","isDef":1},{"term":"Prediction Markets & InfoFi","name":"","def":"Information Finance (InfoFi), a sector using on-chain prediction markets, attention incentives, and reputation staking to aggregate, price, and verify real-world event probabilities and information.","path":"learn/231-en.html","title":"Prediction Markets & InfoFi","g":"web3","isDef":1},{"term":"Price Action","name":"","def":"Price Action (naked-chart analysis) reads swing highs and lows, push-versus-pullback candle behavior, and reactions at key levels directly from the price bars, helping you answer whether the market is stepping up, stepping down, or overlapping sideways without relying on lagging indicators.","path":"learn/115-en.html","title":"Price Action","g":"market","isDef":1},{"term":"Price Relative","name":"","def":"Price Relative (Relative Strength Ratio) divides Asset A's price by Asset B's price (A / B) to track whether the ratio is rising or falling over time.","path":"learn/40-en.html","title":"Price Relative","g":"market","isDef":1},{"term":"Pring Special K","name":"","def":"Aggregate smoothed rates of change across many short, intermediate, and long lookback windows into a single curve to observe the broader multi-horizon momentum backdrop.","path":"learn/72-en.html","title":"Pring Special K","g":"market","isDef":1},{"term":"Producer Price Index (PPI), Final Demand","name":"","def":"Tracks selling prices received by domestic producers.","path":"info/learn/5-en.html","title":"Producer Price Index (PPI), Final Demand","g":"info","isDef":1},{"term":"Profile","name":"Time Price Opportunity","def":"a charting method that divides each session into fixed time blocks—typically 30-minute periods labeled A, B, C—and stacks a letter at every price row visited during that block","path":"learn/100-en.html","title":"TPO/Market Profile","g":"market"},{"term":"Pullbacks & Second Entries","name":"","def":"In a pullback within an uptrend, the first bar whose high exceeds the prior bar’s high is High 1 (H1).","path":"learn/132-en.html","title":"Pullbacks & Second Entries","g":"market","isDef":1},{"term":"PVI","name":"","def":"Isolate and accumulate price performance strictly on bars where trading volume exceeded the prior bar's volume.","path":"learn/83-en.html","title":"PVI","g":"market","isDef":1},{"term":"PVO","name":"","def":"The Percentage Volume Oscillator (PVO) measures by what percentage a short-term EMA of volume sits above or below a longer-term EMA of volume.","path":"learn/36-en.html","title":"PVO","g":"market","isDef":1},{"term":"PVT","name":"","def":"Price Volume Trend (PVT) multiplies each bar's percentage close change by that bar's volume and adds the result to a running cumulative total.","path":"learn/35-en.html","title":"PVT","g":"market","isDef":1},{"term":"R-Squared","name":"R²","def":"Coefficient of Determination","path":"learn/55-en.html","title":"Linear Regression R²","g":"market"},{"term":"RCI","name":"","def":"Measure how closely the rank order of closing prices (from lowest to highest) matches the chronological order of time (from earliest to latest) inside a lookback window.","path":"learn/68-en.html","title":"RCI","g":"market","isDef":1},{"term":"Reading Financial Statements","name":"","def":"The three financial statements are the standardized reporting framework: the Income Statement (Net Income = Revenue - Expenses - Taxes) measures operational profitability over a period; the Balance Sheet (Assets = Liabilities + Equity) captures financial condition at a point in time; and the Cash Flow Statement (Ending Cash = Beginning Cash + Operating + Investing + Financing Cash Flows) tracks actual cash inflows and outflows.","path":"learn/184-en.html","title":"Reading Financial Statements","g":"market","isDef":1},{"term":"Real Gross Domestic Income (GDI)","name":"","def":"Adds income earned from production, such as compensation and profits.","path":"info/learn/22-en.html","title":"Real Gross Domestic Income (GDI)","g":"info","isDef":1},{"term":"Real Gross Domestic Product (GDP)","name":"","def":"Real GDP measures final goods and services produced within the US, adjusted for price changes: an output-side national scorecard.","path":"info/learn/21-en.html","title":"Real Gross Domestic Product (GDP)","g":"info","isDef":1},{"term":"Real Personal Consumption Expenditures","name":"","def":"Price-adjusted household consumption of goods and services, used to assess the volume of demand rather than dollar spending alone.","path":"info/learn/33-en.html","title":"Real Personal Consumption Expenditures","g":"info","isDef":1},{"term":"Rectangles","name":"","def":"A rectangle forms when price moves between two roughly horizontal lines, touching the top at least twice and the bottom at least twice; a close beyond either is a breakout.","path":"learn/152-en.html","title":"Rectangles","g":"market","isDef":1},{"term":"Relative","name":"Relative Strength Ratio","def":"a line calculated simply by dividing Asset A's price by Benchmark B's price","path":"learn/40-en.html","title":"Price Relative","g":"market"},{"term":"Relative Vigor Index","name":"","def":"Compare a bar's net intrabar progress (Close − Open) against its total intrabar range (High − Low) to see whether bars have been consistently finishing near their highs or lows relative to where they opened.","path":"learn/66-en.html","title":"Relative Vigor Index","g":"market","isDef":1},{"term":"Relative Volatility Index","name":"","def":"Compare price volatility on up-close bars against price volatility on down-close bars to see which directional side carries greater volatility weight on a 0 to 100 scale.","path":"learn/67-en.html","title":"Relative Volatility Index","g":"market","isDef":1},{"term":"Relative Volume at Time","name":"","def":"Relative Volume at Time answers 'how busy is trading right now compared with the exact same clock time across prior sessions?' Volume counts how many shares, coins, or contracts traded—not percentage price gain or participant headcount.","path":"learn/86-en.html","title":"Relative Volume at Time","g":"market","isDef":1},{"term":"Renko Charts","name":"","def":"A Renko chart draws a brick only when price has moved a fixed amount (the brick size): a close at least one brick above the top of the last brick adds an up brick; a reversal needs a close at least two bricks below the top (one brick below the bottom) to add a down brick.","path":"learn/160-en.html","title":"Renko Charts","g":"market","isDef":1},{"term":"Reserve Balances of Depository Institutions","name":"","def":"Reserve Balances of Depository Institutions (commonly called Bank Reserves), published weekly in the Federal Reserve's H.4.1 release and monthly in the H.6 release, measure the total dollar balances that commercial banks and other depository institutions hold in their master accounts at Federal Reserve Banks.","path":"info/learn/52-en.html","title":"Reserve Balances of Depository Institutions","g":"info","isDef":1},{"term":"Retail Sales Control Group","name":"","def":"A common analytical grouping excludes autos, gasoline, building materials and food services to inform estimates of underlying goods consumption.","path":"info/learn/32-en.html","title":"Retail Sales Control Group","g":"info","isDef":1},{"term":"Rising & Falling Wedges","name":"","def":"Rising wedge: swing highs and lows both rise, but the lows rise faster, so the two lines converge upward; a close below the lower line is a downside break.","path":"learn/153-en.html","title":"Rising & Falling Wedges","g":"market","isDef":1},{"term":"ROC","name":"","def":"Rate of Change (ROC) directly answers 'by what percentage has price risen or fallen compared with N bars ago?' Converting price differences into percentages makes it easy to track how momentum over a fixed span is evolving.","path":"learn/16-en.html","title":"ROC","g":"market","isDef":1},{"term":"Rounding Bottoms & V Reversals","name":"","def":"A rounding bottom forms when a decline slows, price lingers sideways at the lows for a while, and then gradually rises, tracing a gentle U.","path":"learn/155-en.html","title":"Rounding Bottoms & V Reversals","g":"market","isDef":1},{"term":"RSI","name":"","def":"The Relative Strength Index (RSI) converts the average size of recent price gains versus average losses into a score between 0 and 100.","path":"learn/11-en.html","title":"RSI","g":"market","isDef":1},{"term":"RVOL","name":"","def":"Relative Volume (RVOL) divides current volume by normal benchmark volume to answer 'how many times busier than usual is trading right now?' A reading of 1 matches the benchmark; 2 means twice the benchmark.","path":"learn/33-en.html","title":"RVOL","g":"market","isDef":1},{"term":"RWA: Real-World Assets On-Chain","name":"","def":"The process of mapping ownership or yield rights of off-chain traditional assets—such as government bonds, real estate, or receivables—onto the blockchain as tokens via legal structures and smart contracts.","path":"learn/214-en.html","title":"RWA: Real-World Assets On-Chain","g":"web3","isDef":1},{"term":"S&P Cotality Case-Shiller Home Price Indices","name":"","def":"The S&P Cotality (formerly CoreLogic) Case-Shiller Home Price Indices, published monthly by S&P Dow Jones Indices, use the repeat-sales methodology developed by Karl Case and Robert Shiller to track price changes across matched sales of the exact same single-family homes over time.","path":"info/learn/46-en.html","title":"S&P Cotality Case-Shiller Home Price Indices","g":"info","isDef":1},{"term":"S&P Global US Manufacturing PMI","name":"","def":"S&P Global’s monthly US manufacturing survey.","path":"info/learn/25-en.html","title":"S&P Global US Manufacturing PMI","g":"info","isDef":1},{"term":"S&P Global US Services PMI Business Activity Index","name":"","def":"The S&P US services headline is a business activity index, not a simple average of every service-sector subindex.","path":"info/learn/26-en.html","title":"S&P Global US Services PMI Business Activity Index","g":"info","isDef":1},{"term":"SAR","name":"Stop and Reverse","def":"an overlay plotting a trail of dots below or above price that accelerates closer each time a new extreme is reached and flips sides when touched","path":"learn/38-en.html","title":"Parabolic SAR","g":"market"},{"term":"Seasonality & Calendar Effects","name":"","def":"Seasonality and Calendar Effects refer to empirical market anomalies where asset returns exhibit historical statistical deviations during specific months, quarters, days of the week, or holiday windows.","path":"learn/192-en.html","title":"Seasonality & Calendar Effects","g":"market","isDef":1},{"term":"Secured Overnight Financing Rate SOFR","name":"","def":"The Secured Overnight Financing Rate (SOFR), published jointly by the Federal Reserve Bank of New York and the Office of Financial Research (OFR), is a broad benchmark interest rate measuring the cost of borrowing cash overnight collateralized by U.S. Treasury securities in the repurchase agreement (repo) market. Because it is grounded in over a trillion dollars of actual daily Treasury repo transactions rather than survey quotes, SOFR serves as the primary thermometer for U.S. dollar overnight funding conditions.","path":"info/learn/59-en.html","title":"Secured Overnight Financing Rate SOFR","g":"info","isDef":1},{"term":"Senior Loan Officer Opinion Survey SLOOS","name":"","def":"The Senior Loan Officer Opinion Survey on Bank Lending Practices (SLOOS) is a quarterly qualitative survey conducted by the Federal Reserve that asks senior loan officers at domestic and U.S. branches of foreign commercial banks two distinct sets of questions over the past three months: did your bank tighten or ease credit approval standards, and did borrower demand for loans strengthen or weaken?","path":"info/learn/58-en.html","title":"Senior Loan Officer Opinion Survey SLOOS","g":"info","isDef":1},{"term":"Shooting Star & Inverted Hammer","name":"","def":"Shape: an upper shadow at least twice the body, a short lower shadow (no longer than the body), and the body in the lower part of the range.","path":"learn/142-en.html","title":"Shooting Star & Inverted Hammer","g":"market","isDef":1},{"term":"SMA","name":"","def":"The Simple Moving Average (SMA) compresses a recent stretch of prices into a single average line to help answer whether the broader backdrop is rising, falling, or moving sideways.","path":"learn/1-en.html","title":"SMA","g":"market","isDef":1},{"term":"Smart Contracts & Token Approvals","name":"","def":"A smart contract is a program on a blockchain that executes automatically when its conditions are met.","path":"learn/203-en.html","title":"Smart Contracts & Token Approvals","g":"web3","isDef":1},{"term":"Smart Money Concepts (SMC)","name":"","def":"SMC (Smart Money Concepts) links prior swing highs/lows (liquidity pools), structural breaks (BOS/CHOCH), and the last opposing candle before a strong displacement move (Order Block, OB) into a structured chart workflow, helping you answer where a strong move originated and which exact price level invalidates a pullback idea. 'Smart money' is a narrative label for price action; candlesticks cannot reveal institutional account identities.","path":"learn/123-en.html","title":"Smart Money Concepts (SMC)","g":"market","isDef":1},{"term":"SMC","name":"Smart Money Concepts","def":"a modern chart-reading workflow combining prior highs/lows as liquidity zones, structural breaks BOS/CHOCH, and the last opposing candle before a strong move as an Order Block","path":"learn/123-en.html","title":"Smart Money Concepts (SMC)","g":"market"},{"term":"SMI","name":"","def":"Measure whether the closing price sits in the upper half or lower half of its recent high-low range, then double-smooth that distance relative to the double-smoothed range width.","path":"learn/64-en.html","title":"SMI","g":"market","isDef":1},{"term":"SMI Ergodic","name":"","def":"Compare double-smoothed net price changes against double-smoothed absolute price changes (matching the True Strength Index formula) and pair that main line with a slower signal EMA to see whether directional momentum is improving.","path":"learn/65-en.html","title":"SMI Ergodic","g":"market","isDef":1},{"term":"SMMA/RMA","name":"","def":"The Smoothed Moving Average / Running Moving Average (SMMA / RMA) blends new prices into the prior average very gradually; a standard N-period RMA gives the newest price a weight of just 1/N.","path":"learn/4-en.html","title":"SMMA/RMA","g":"market","isDef":1},{"term":"SocialFi: Tokenising Social Graphs","name":"","def":"The combination of decentralized identity, on-chain social graphs, and tokenomics to give users ownership over their social connections and monetize content or influence.","path":"learn/229-en.html","title":"SocialFi: Tokenising Social Graphs","g":"web3","isDef":1},{"term":"Spot, Margin & Leveraged Contracts","name":"","def":"Spot means buying the asset itself with your full funds; a drop is only a paper loss and you are not forced out (unless you borrowed).","path":"learn/182-en.html","title":"Spot, Margin & Leveraged Contracts","g":"web3","isDef":1},{"term":"Stablecoin Reserve and Attestation Reports","name":"","def":"Stablecoin Reserve and Attestation Reports are periodic disclosures published by fiat-backed stablecoin issuers (such as the issuers of USDC or USDT) accompanied by independent third-party accountant attestation reports.","path":"info/learn/65-en.html","title":"Stablecoin Reserve and Attestation Reports","g":"info","isDef":1},{"term":"Stablecoins Basics","name":"","def":"A stablecoin is a crypto token designed to hold a target price, most often 1 US dollar.","path":"learn/181-en.html","title":"Stablecoins Basics","g":"web3","isDef":1},{"term":"Staking, Liquid Staking & Restaking","name":"","def":"Staking locks tokens in a proof-of-stake network to help validate and earn rewards.","path":"learn/207-en.html","title":"Staking, Liquid Staking & Restaking","g":"web3","isDef":1},{"term":"Standard Deviation","name":"","def":"Standard Deviation condenses how widely a recent set of prices is dispersed around its own average into a single number: readings are small when prices cluster tightly near the mean and large when prices spread far apart.","path":"learn/30-en.html","title":"Standard Deviation","g":"market","isDef":1},{"term":"Stochastic/KD","name":"","def":"The Stochastic Oscillator (KD) measures where the closing price sits within the high-low range of a recent lookback window: closes near the top of the range produce high readings, while closes near the bottom produce low readings. %K is the faster line and %D is a moving average of %K.","path":"learn/13-en.html","title":"Stochastic/KD","g":"market","isDef":1},{"term":"StochRSI","name":"","def":"Measure where the RSI momentum oscillator currently sits within its own recent high-low range.","path":"learn/57-en.html","title":"StochRSI","g":"market","isDef":1},{"term":"Strategy","name":"Ascending","def":"Descending, Symmetrical","path":"learn/150-en.html","title":"Triangles","g":"market"},{"term":"Supertrend","name":"","def":"Supertrend uses Average True Range (ATR) and a multiplier to plot a trailing reference line on one side of price, flipping to the opposite side when price crosses the line.","path":"learn/39-en.html","title":"Supertrend","g":"market","isDef":1},{"term":"Supply","name":"Inventory divided by the monthly sales pace","def":"where 4 to 6 months is traditionally considered balanced","path":"info/learn/43-en.html","title":"Existing-Home Sales","g":"info"},{"term":"Supply and Demand Zones","name":"","def":"Supply and Demand Zone analysis marks compact consolidation bases from which price previously departed with a rapid, wide-range move, helping you answer where a sharp historical imbalance originated and how price behaves if it revisits that base.","path":"learn/127-en.html","title":"Supply and Demand Zones","g":"market","isDef":1},{"term":"Support and Resistance","name":"","def":"Support and Resistance mark horizontal price zones where past declines repeatedly paused or bounced (support) and past advances repeatedly stalled or pulled back (resistance), helping you answer where buyers or sellers previously stepped in noticeably.","path":"learn/111-en.html","title":"Support and Resistance","g":"market","isDef":1},{"term":"TD Sequential","name":"","def":"TD Sequential has two phases.","path":"learn/158-en.html","title":"TD Sequential","g":"market","isDef":1},{"term":"Technical Roles in Web3","name":"","def":"The engineering career landscape in Web3 spanning smart contract development, security auditing, full-stack dApp integration, and core protocol/cryptography engineering.","path":"learn/222-en.html","title":"Technical Roles in Web3","g":"web3","isDef":1},{"term":"TEMA","name":"","def":"The Triple Exponential Moving Average (TEMA) combines three EMA layers into a single price line using 3×EMA1 − 3×EMA2 + EMA3 to further reduce moving-average lag. 'Triple' refers to the three smoothing layers in the formula, not three independent pieces of evidence.","path":"learn/8-en.html","title":"TEMA","g":"market","isDef":1},{"term":"The Doji Family","name":"","def":"A doji has a body smaller than 10% of its range.","path":"learn/143-en.html","title":"The Doji Family","g":"market","isDef":1},{"term":"Theory","name":"Chanlun","def":"a hierarchical chart-segmentation method introduced under the pen name 'Chan Zhong Shuo Chan' that merges nested candles and builds Fractals, Strokes, Segments, and overlapping Centers","path":"learn/122-en.html","title":"Chan Theory (Chan Lun)","g":"market","more":[{"path":"learn/126-en.html","title":"Auction Market Theory"}]},{"term":"Three White Soldiers & Three Black Crows","name":"","def":"Three white soldiers: three consecutive bullish bars, each closing above the prior close, each with an upper shadow no more than 30% of its range (closing near the high).","path":"learn/145-en.html","title":"Three White Soldiers & Three Black Crows","g":"market","isDef":1},{"term":"Time","name":"RVOL at Time","def":"an indicator dividing current bar or cumulative session volume by the average volume at the exact same time of day over the past N days","path":"learn/86-en.html","title":"Relative Volume at Time","g":"market"},{"term":"Tokenomics: Supply, FDV & Unlocks","name":"","def":"Tokenomics covers how a token is issued, allocated, released and used.","path":"learn/204-en.html","title":"Tokenomics: Supply, FDV & Unlocks","g":"web3","isDef":1},{"term":"Total Social Financing (TSF)","name":"","def":"Looking only at bank loans misses massive funding channels like government bonds, corporate bonds, and equity issuance.","path":"info/learn/78-en.html","title":"Total Social Financing (TSF)","g":"info","isDef":1},{"term":"TPO/Market Profile","name":"","def":"TPO (Time Price Opportunity, or Market Profile) slices each session into fixed time blocks (such as 30-minute periods labeled A, B, C) and records which price rows were visited in each block, helping you answer where price spent the most time versus where it passed through briefly.","path":"learn/100-en.html","title":"TPO/Market Profile","g":"market","isDef":1},{"term":"Trading","name":"Chinese edition","def":"translated by Zhu Jia, China Youth Press, 2020, ISBN 978-7-5153-6031-7; Japanese original published by KADOKAWA, 2018","path":"learn/31-en.html","title":"Historical Volatility","g":"market","more":[{"path":"learn/56-en.html","title":"Correlation Coefficient"},{"path":"learn/110-en.html","title":"Liquidations"},{"path":"learn/132-en.html","title":"Pullbacks & Second Entries"}]},{"term":"Trading Plan & Journal","name":"","def":"A Trading Plan is a pre-trade written rulebook specifying the target asset, entry trigger, position size (Max Acceptable Dollar Risk / Stop Distance per Share), invalidation stop-loss, and exit criteria; a Trading Journal is a post-trade ledger documenting execution metrics, rule deviations, and emotional states.","path":"learn/191-en.html","title":"Trading Plan & Journal","g":"market","isDef":1},{"term":"Trading Psychology & Biases","name":"","def":"Common biases in trading include the gambler’s fallacy (thinking a run of gains means a fall is “due,” or a run of losses means a win is due), loss aversion (a loss hurts more than an equal gain pleases), the disposition effect (selling winners too early and holding losers too long), anchoring (judging cheap or expensive against a past price) and hindsight bias (treating explanations written afterwards as if they were foreseeable).","path":"learn/173-en.html","title":"Trading Psychology & Biases","g":"market","isDef":1},{"term":"Trading Ranges","name":"","def":"A trading range is a stretch of bars in which price swings back and forth between roughly fixed upper and lower bounds without a persistent series of higher highs and higher lows (or lower highs and lower lows).","path":"learn/134-en.html","title":"Trading Ranges","g":"market","isDef":1},{"term":"Treasury General Account TGA","name":"","def":"The Treasury General Account (TGA) is the U.S. Treasury's official operational cash account held at the Federal Reserve; tax receipts and proceeds from Treasury debt issuance flow into this account, while federal benefit payments, vendor outlays, and maturing debt redemptions flow out. Crucially, the TGA records a point-in-time cash balance (a stock) rather than the daily or monthly federal budget deficit (a flow), nor is it discretionary money that the Federal Reserve can spend on its own.","path":"info/learn/54-en.html","title":"Treasury General Account TGA","g":"info","isDef":1},{"term":"Trend Bars & Doji","name":"","def":"A trend bar has a body covering most of its range and a close near one end of the range; a doji has an open very close to its close and a small body, here taken as a body smaller than one tenth of the range.","path":"learn/128-en.html","title":"Trend Bars & Doji","g":"market","isDef":1},{"term":"Trend Lines and Channels","name":"","def":"Trendlines and Channels connect a sequence of rising swing lows (or falling swing highs) with a straight diagonal line and a parallel opposite boundary, helping you answer what slope price has been following and whether that pace is holding, steepening, or breaking down.","path":"learn/112-en.html","title":"Trend Lines and Channels","g":"market","isDef":1},{"term":"Trend vs Range","name":"","def":"A trend is a stretch of bars in which swing highs and lows advance in one direction (higher highs and higher lows in an uptrend), most closes sit on one side, and moving averages slope clearly.","path":"learn/169-en.html","title":"Trend vs Range","g":"market","isDef":1},{"term":"Triangles","name":"","def":"A triangle forms when lines through the swing highs and through the swing lows converge to the right.","path":"learn/150-en.html","title":"Triangles","g":"market","isDef":1},{"term":"Triple Screen","name":"","def":"Triple Screen assigns jobs to three timeframes about five times apart: screen one (long, e.g. weekly) uses a trend indicator to set the only direction to trade; screen two (intermediate, e.g. daily) uses an oscillator to find pullbacks against that trend, such as an oversold reading in an uptrend; screen three (short or intraday) uses price itself for entry, such as a buy stop above the prior bar’s high.","path":"learn/167-en.html","title":"Triple Screen","g":"market","isDef":1},{"term":"TRIX","name":"","def":"See whether the 1-bar percentage rate of change of a triple-smoothed EMA is positive or negative.","path":"learn/61-en.html","title":"TRIX","g":"market","isDef":1},{"term":"True Strength Index","name":"","def":"Double-smooth bar-to-bar price changes and divide by double-smoothed absolute price changes to see whether net momentum points up or down.","path":"learn/60-en.html","title":"True Strength Index","g":"market","isDef":1},{"term":"TTM Squeeze","name":"","def":"TTM Squeeze separates two distinct questions: first, whether price volatility is compressed tighter than usual, and second, which way momentum is leaning once that compression releases.","path":"learn/87-en.html","title":"TTM Squeeze","g":"market","isDef":1},{"term":"Turtle Trading","name":"","def":"Turtle trading is a rule-based trend-following system.","path":"learn/166-en.html","title":"Turtle Trading","g":"market","isDef":1},{"term":"U.S. Dollar Index (DXY)","name":"","def":"The U.S. Dollar Index (DXY) measures the strength of the U.S. dollar against a basket of six major foreign currencies. Because global commodities, cross-border debt, and major crypto stablecoins are denominated in USD, DXY shifts reflect global dollar liquidity conditions.","path":"info/learn/73-en.html","title":"U.S. Dollar Index (DXY)","g":"info","isDef":1},{"term":"U.S. Treasury Auction Results","name":"","def":"U.S. Treasury Auction Results record the pricing and allotment details when the U.S. Department of the Treasury sells newly issued marketable debt (including Treasury Bills, Notes, Bonds, TIPS, and Floating Rate Notes) in the primary market. These releases directly reveal the yield and price global institutional and retail investors demand to absorb incoming federal debt supply.","path":"info/learn/61-en.html","title":"U.S. Treasury Auction Results","g":"info","isDef":1},{"term":"U.S. Treasury Yields and the Yield Curve","name":"","def":"U.S. Treasury yields act as the gravitational benchmark for global asset pricing. Bond prices and yields move inversely: when buyers bid up Treasury prices, yields fall; when sellers dump bonds, yields rise. Tracking the 2-year and 10-year yields and the curve shape is essential for reading macro liquidity.","path":"info/learn/72-en.html","title":"U.S. Treasury Yields and the Yield Curve","g":"info","isDef":1},{"term":"Ulcer Index","name":"","def":"The Ulcer Index specifically measures the depth and duration of percentage drawdowns from recent rolling peak prices.","path":"learn/88-en.html","title":"Ulcer Index","g":"market","isDef":1},{"term":"Ultimate Oscillator","name":"","def":"Blend price-push ratios across short, medium, and long lookback windows (typically 7, 14, and 28 bars) into a single score to reduce the blind spots of any single period length.","path":"learn/62-en.html","title":"Ultimate Oscillator","g":"market","isDef":1},{"term":"Unemployment Rate (U-3)","name":"","def":"The unemployed share of the labor force: people without work who are available and meet active-search criteria, rather than a share of all residents.","path":"info/learn/12-en.html","title":"Unemployment Rate (U-3)","g":"info","isDef":1},{"term":"University of Michigan Consumer Sentiment Index","name":"","def":"The University of Michigan Consumer Sentiment Index, published twice a month (Preliminary mid-month and Final at month-end) by the University of Michigan Surveys of Consumers, gauges U.S. households' views on their personal finances, general business conditions, and big-ticket buying conditions, alongside closely watched 1-year and 5–10-year inflation expectations.","path":"info/learn/38-en.html","title":"University of Michigan Consumer Sentiment Index","g":"info","isDef":1},{"term":"University of Michigan Inflation Expectations","name":"","def":"Surveys how much consumers expect prices to rise annually; expectations are not measured current inflation.","path":"info/learn/10-en.html","title":"University of Michigan Inflation Expectations","g":"info","isDef":1},{"term":"Valuation Multiples: P/E, P/B, and P/S","name":"","def":"Valuation multiples evaluate relative share pricing against operational fundamentals.","path":"learn/185-en.html","title":"Valuation Multiples: P/E, P/B, and P/S","g":"market","isDef":1},{"term":"Vertical Spreads","name":"","def":"A Vertical Spread involves simultaneously buying 1 option and selling 1 option of the exact same type (both Calls or both Puts) on the same underlying asset and with the same expiration date, but at different strike prices.","path":"learn/213-en.html","title":"Vertical Spreads","g":"market","isDef":1},{"term":"Volatility","name":"HV","def":"an indicator calculating the standard deviation of bar-to-bar logarithmic returns over N bars and scaling it to an annualized percentage","path":"learn/31-en.html","title":"Historical Volatility","g":"market"},{"term":"Volatility Smile & Skew","name":"","def":"Volatility Smile and Volatility Skew (or Smirk) describe the pattern in which options on the same underlying and expiration date carry different Implied Volatilities (IV) across strike prices rather than a flat line: when both low-strike and high-strike options trade at higher IVs than at-the-money (ATM) options in a U-shaped curve, it is called a Volatility Smile; when IV slopes asymmetrically toward one side (commonly higher IV at lower strikes in equity index options), it is called Volatility Skew.","path":"learn/211-en.html","title":"Volatility Smile & Skew","g":"market","isDef":1},{"term":"Volatility Stop","name":"","def":"Volatility Stop is a family of trailing exit methods that leave a wider buffer when recent price swings are large and a tighter buffer when recent swings are small.","path":"learn/92-en.html","title":"Volatility Stop","g":"market","isDef":1},{"term":"Volume","name":"","def":"Trading Volume records how many shares, coins, or contracts changed hands inside a single bar, while a Volume Moving Average (Volume MA) shows the typical level over the last N bars.","path":"learn/32-en.html","title":"Volume","g":"market","isDef":1},{"term":"Volume and Price","name":"","def":"Volume–price analysis sorts each move into four combinations: rising price on rising volume, rising price on falling volume, falling price on rising volume, and falling price on falling volume.","path":"learn/157-en.html","title":"Volume and Price","g":"market","isDef":1},{"term":"Volume Delta","name":"","def":"Volume Delta compares the volume classified as 'positive (up/buying-side)' against the volume classified as 'negative (down/selling-side)' inside a single candlestick: Volume Delta = Up Volume − Down Volume.","path":"learn/101-en.html","title":"Volume Delta","g":"market","isDef":1},{"term":"Volume Footprint","name":"","def":"A Volume Footprint chart opens up each candle to display classified sell volume and buy volume at every price row inside the bar, helping you answer where inside the candle trading was heaviest and which side was more aggressive.","path":"learn/103-en.html","title":"Volume Footprint","g":"market","isDef":1},{"term":"Volume Profile","name":"","def":"Volume Profile stacks traded volume horizontally by price level rather than vertically by time, helping you answer which price zones saw the heaviest trading activity over a selected window.","path":"learn/99-en.html","title":"Volume Profile","g":"market","isDef":1},{"term":"Vortex","name":"","def":"Compare upward versus downward bar-to-bar movement across adjacent candlesticks: the Vortex Indicator plots VI+ (from current highs minus prior lows) and VI− (from current lows minus prior highs), both scaled by True Range, to highlight shifts in directional structure.","path":"learn/45-en.html","title":"Vortex","g":"market","isDef":1},{"term":"VWAP","name":"","def":"Volume Weighted Average Price (VWAP) accumulates (Price × Volume) from a chosen anchor start point and divides by cumulative volume from that same start point, producing the volume-weighted average price of the session.","path":"learn/37-en.html","title":"VWAP","g":"market","isDef":1,"more":[{"path":"learn/93-en.html","title":"Anchored VWAP"}]},{"term":"VWMA","name":"","def":"The Volume Weighted Moving Average (VWMA) weights the last N closing prices by each bar's trading volume: bars with heavier volume exert a larger pull on the average price.","path":"learn/5-en.html","title":"VWMA","g":"market","isDef":1},{"term":"Wallets & Exchange Custody","name":"","def":"Custodial: assets sit in an exchange account, the exchange holds the private keys, and you sign in with your credentials.","path":"learn/180-en.html","title":"Wallets & Exchange Custody","g":"web3","isDef":1},{"term":"Wedges & Three Pushes","name":"","def":"Three pushes: three consecutive swing highs (or lows) in one direction, each beyond the last, with each advance smaller than the one before.","path":"learn/133-en.html","title":"Wedges & Three Pushes","g":"market","isDef":1},{"term":"What a Stock Is","name":"","def":"A share of stock is a unit of ownership in a company.","path":"learn/175-en.html","title":"What a Stock Is","g":"market","isDef":1},{"term":"What Crypto Assets Are","name":"","def":"Crypto assets are digital assets recorded on a blockchain: an ordered chain of transaction records maintained by many nodes, which makes rewriting history costly.","path":"learn/179-en.html","title":"What Crypto Assets Are","g":"web3","isDef":1},{"term":"Williams %R","name":"","def":"Williams %R also measures where the closing price sits within the recent high-low range, but plots it on an inverted 0 to −100 scale: readings near 0 sit near the top of the range, while readings near −100 sit near the bottom.","path":"learn/14-en.html","title":"Williams %R","g":"market","isDef":1},{"term":"Williams Alligator","name":"","def":"Use three smoothed moving averages of different speeds—shifted slightly forward—to see whether price action has transitioned from tangled congestion into an orderly directional run.","path":"learn/48-en.html","title":"Williams Alligator","g":"market","isDef":1},{"term":"Williams Fractals","name":"","def":"Williams Fractals mark local five-bar (or N-bar) peaks and valleys on a price chart.","path":"learn/97-en.html","title":"Williams Fractals","g":"market","isDef":1},{"term":"WMA","name":"","def":"The Weighted Moving Average (WMA) averages the last N bars using uneven weights; the standard linear version gives the largest weight to the newest bar and progressively smaller weights to older bars.","path":"learn/3-en.html","title":"WMA","g":"market","isDef":1},{"term":"Wyckoff Method","name":"","def":"The Wyckoff Method compares price swings and bar ranges with volume across a trading range, helping you answer whether selling pressure is drying up near range lows (accumulation candidate) or buying power is stalling near range highs (distribution candidate).","path":"learn/118-en.html","title":"Wyckoff Method","g":"market","isDef":1},{"term":"Yield Aggregators & Restaking","name":"","def":"Yield aggregators are smart contract vaults that automate reward harvesting and compounding across DeFi protocols, while restaking reuses staked assets to secure additional middleware networks for stacked yields.","path":"learn/225-en.html","title":"Yield Aggregators & Restaking","g":"web3","isDef":1},{"term":"ZigZag","name":"","def":"ZigZag filters out minor price fluctuations smaller than a chosen threshold and connects significant swing highs and swing lows with straight lines, letting you see the broad skeleton of historical price swings.","path":"learn/98-en.html","title":"ZigZag","g":"market","isDef":1}];
